import React, { useEffect, useState } from 'react';
import Feedback from './Feedback';
import Donate from './Donate';
import Volunteer from './Volunteer';

export default function VolunteerDonorSection({ me, events, token, setMsg, activities }) {
  const [achievements, setAchievements] = useState(null);

  useEffect(()=>{
    if (!token) return;
    fetch((process.env.REACT_APP_API || 'http://localhost:4000') + '/api/actions/achievements',{headers:{Authorization:`Bearer ${token}`}})
      .then(r=>r.json()).then(d=>{ setAchievements(d); }).catch(e=>{});
  },[token]);

  return (
    <div className="panel">
      <h3>Recognition & Badges</h3>
      <div className="cards">
        <div className="stat-card">
          <div className="stat-num">{me.points || 0}</div>
          <div className="stat-label">Points</div>
        </div>
        <div className="stat-card">
          <div className="stat-num">{achievements ? achievements.summary.totalVolunteers : '-'}</div>
          <div className="stat-label">Volunteered</div>
        </div>
        <div className="stat-card">
          <div className="stat-num">{achievements ? achievements.summary.totalDonations : '-'}</div>
          <div className="stat-label">Donations</div>
        </div>
      </div>

      <p style={{marginTop:12}}><strong>Name:</strong> {me.name}</p>
      <p><strong>Email:</strong> {me.email}</p>

      <p><strong>Level:</strong> {
        me.points >= 200 ? 'Gold' :
        me.points >= 100 ? 'Silver' :
        me.points >= 50  ? 'Bronze' :
        me.points >= 10  ? 'Member' : 'New'
      }</p>

      <h4>Give Feedback</h4>
      <Feedback token={token} setMsg={setMsg} />

      <h4>Donate</h4>
      <Donate token={token} setMsg={setMsg} />

      <h4>Volunteer for Event</h4>
      <Volunteer token={token} events={events} setMsg={setMsg} />

      <h4 style={{marginTop:18}}>Achievements</h4>
      {achievements ? (
        <div>
          <p><strong>Total Volunteered:</strong> {achievements.summary.totalVolunteers}</p>
          <p><strong>Total Donations:</strong> {achievements.summary.totalDonations} (₹{achievements.summary.donatedSum})</p>

          <div style={{marginTop:10}}>
            <h5>Recent Volunteering</h5>
            {achievements.volunteers.length ? achievements.volunteers.map(v=>(
              <div key={v.id} className="small-item">{new Date(v.created_at).toLocaleDateString()} — {v.event_title}</div>
            )) : <p>No volunteering records yet.</p>}
          </div>

          <div style={{marginTop:10}}>
            <h5>Recent Donations</h5>
            {achievements.donations.length ? achievements.donations.map(d=> (
              <div key={d.id} className="small-item">{new Date(d.created_at).toLocaleDateString()} — ₹{d.amount} {d.ngo_name ? `to ${d.ngo_name}` : ''}</div>
            )) : <p>No donations yet.</p>}
          </div>
        </div>
      ) : (
        <p>Loading achievements...</p>
      )}
    </div>
  );
}
